description:
[
  {
    "topic": "US weekly initial jobless claims / labor-market data ahead of payrolls",
    "why_gold_cares": "Labor softness pulls forward Fed cut pricing, lowers front-end real yields and DXY, supporting gold",
    "impact_threshold": "Large surprise versus consensus or a multi-week trend break that shifts rate-cut odds",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Fed speakers / FOMC communication and rate-path repricing",
    "why_gold_cares": "Gold is a zero-coupon asset; shifts in expected policy path move real yields directly",
    "impact_threshold": "Voting members explicitly changing tone on cuts/hikes or balance-sheet policy",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "10Y real yield (TIPS) and nominal curve moves",
    "why_gold_cares": "Real yield is the core opportunity-cost input for gold valuation",
    "impact_threshold": "Fast intraday moves in TIPS yields, especially disorderly bear steepening or sharp bull flattening",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "DXY / major FX moves (JPY, EUR, CNY fix)",
    "why_gold_cares": "Dollar is the pricing numeraire; weaker DXY mechanically lifts XAUUSD and boosts non-US demand",
    "impact_threshold": "Broad, sustained dollar move rather than a narrow single-pair drift",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Treasury supply: coupon auctions, TGA rebuild and bill issuance",
    "why_gold_cares": "Weak auction demand pressures term premium and can hit both bonds and dollar confidence; TGA rebuild drains liquidity",
    "impact_threshold": "Tailing auctions, weak indirect bids, or unusually rapid cash-balance rebuild",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Geopolitical shocks: Middle East, Russia/Ukraine, Asia-Pacific escalation or ceasefire",
    "why_gold_cares": "Safe-haven bid and hedging flows repriced instantly on escalation; unwound on credible de-escalation",
    "impact_threshold": "State-level military action, strikes on energy/shipping infrastructure, or signed ceasefire terms",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Fed independence / leadership and political interference headlines",
    "why_gold_cares": "Perceived loss of policy credibility raises inflation-risk premium and debases dollar-reserve confidence",
    "impact_threshold": "Concrete personnel or legal developments, not commentary",
    "directional_risk": "BULLISH_GOLD"
  },
  {
    "topic": "Tariffs, export controls and sanctions announcements",
    "why_gold_cares": "Trade shocks raise inflation and growth uncertainty and can trigger reserve diversification into gold",
    "impact_threshold": "New effective-dated measures on major trading partners or critical goods",
    "directional_risk": "BULLISH_GOLD"
  }
]
